module accu (
    input               clk,
    input               rst_n,
    input       [7:0]   data_in,
    input               valid_in,
    output  reg         valid_out,
    output  reg [9:0]   data_out
);

reg [1:0] counter;
reg [9:0] temp_data;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        counter <= 2'd0;
        data_out <= 10'd0;
        valid_out <= 1'b0;
        temp_data <= 10'd0;
    end else if(valid_in && counter != 2'd3) begin
        counter <= counter + 1;
        temp_data <= temp_data + data_in;
        valid_out <= 1'b0;
    end else if(counter == 2'd3) begin
        counter <= 2'd0;
        data_out <= temp_data + data_in;
        valid_out <= 1'b1;
        temp_data <= 10'd0;
    end else begin
        counter <= counter;
        data_out <= data_out;
        valid_out <= 1'b0;
        temp_data <= temp_data;
    end
end
endmodule
